insert into public.reference_material_aliases (alias_id, material_id, market_code, language_code, alias_text, alias_key, alias_kind, exact_identity, confidence, active)
select alias_id, material_id, market_code, language_code, alias_text, public.normalize_reference_material_alias(alias_text), alias_kind, exact_identity, confidence, true
from _gcm_aliases
on conflict (material_id, market_code, language_code, alias_key) do update set
  alias_text = excluded.alias_text, alias_kind = excluded.alias_kind, exact_identity = excluded.exact_identity, confidence = excluded.confidence, active = true;
update public.material_resolver_versions
set status = 'retired'
where market_code = 'IL' and status = 'active' and resolver_version <> 'material_identity_v2';

insert into public.material_resolver_versions (resolver_version, market_code, algorithm_version, catalog_fingerprint, status, activated_at)
values ('material_identity_v2', 'IL', 'deterministic_v2', 'IL:global_catalog_v1:4436:8872:2026-09-29', 'active', now())
on conflict (resolver_version) do update set
  algorithm_version = excluded.algorithm_version, catalog_fingerprint = excluded.catalog_fingerprint, status = excluded.status, activated_at = now();

select
  (select count(*) from public.reference_materials where active and specifications->>'catalog_version' = 'israel_global_catalog_v1') as catalog_v1_materials,
  (select count(*) from public.reference_material_aliases a join public.reference_materials m on m.material_id = a.material_id where a.active and a.market_code = 'IL' and m.specifications->>'catalog_version' = 'israel_global_catalog_v1') as catalog_v1_aliases,
  (select resolver_version from public.material_resolver_versions where market_code = 'IL' and status = 'active') as active_resolver;

commit;
